SELECT audit_assert('schema', 'migration 001 down removes all domain tables', (SELECT count(*)=0 FROM information_schema.tables WHERE table_schema=current_schema() AND table_name<>'audit_results'), 'down migration dependency order works');

\ir ../migrations/001_init.up.sql

\ir ../migrations/002_add_scrape_run_status_check.up.sql

SELECT audit_assert('schema', 'fresh schema recreated after complete rollback', (SELECT count(*)=12 FROM information_schema.tables WHERE table_schema=current_schema() AND table_name<>'audit_results'), 'all domain tables recreated');
